  // footage: the code-drawn sets rendered for the site (assets/gfx/plate-*.jpg); a speaker is already in plates a and b
  const PL = {}; ['a', 'b', 'desk'].forEach((k) => { const i = new Image(); i.src = `assets/gfx/plate-${k}.jpg`; PL[k] = i; });
  const MP = {}; [['geo', 'map-geo'], ['state', 'map-state'], ['paper', 'map-paper'], ['globe', 'doc-globe'], ['par', 'p-parallax']].forEach(([k, f]) => { const i = new Image(); i.src = `assets/gfx/${f}.jpg`; MP[k] = i; });
  // a full-card picture with a slow push (scale 1 = cover)
