    const g = x.createLinearGradient(cx - s, 0, cx + s, 0); g.addColorStop(0, '#2a2236'); g.addColorStop(1, col); x.fillStyle = g; x.beginPath(); x.ellipse(cx, cy + s * 0.98, s * 0.78, s * 0.52, 0, Math.PI, 0); x.fill(); x.beginPath(); x.ellipse(cx, cy, s * 0.3, s * 0.37, 0, 0, 7); x.fill();
