  const clips = (x, X, Y, w, h, parts, col, k = 0) => { let px = X; const tot = parts.reduce((s, p) => s + Math.abs(p), 0), sc = w / tot; parts.forEach((p) => { const ww = (p < 0 ? -p * (1 - k) : p) * sc; if (p > 0) { rr(x, px + 1, Y, ww - 2, h, 4, col); x.fillStyle = 'rgba(255,255,255,.22)'; x.fillRect(px + 3, Y + 1, Math.max(0, ww - 6), 1); } else if (ww > 1) { rr(x, px + 1, Y, ww - 2, h, 4, 'rgba(255,255,255,.06)'); } px += ww; }); return px; };
