  const scene = (x, X, Y, w, h, hue = 260, sat = 30) => {
    const key = hue >= 130 && hue <= 175 ? 'desk' : hue > 175 && hue < 300 ? 'b' : 'a', img = PL[key];
    if (img && img.complete && img.naturalWidth) { x.save(); x.beginPath(); x.rect(X, Y, w, h); x.clip(); x.filter = sat > 45 ? 'saturate(1.25)' : sat < 20 ? 'saturate(.6)' : 'none'; cover(x, img, X, Y, w, h, key === 'b' ? 0.62 : 0.5); x.filter = 'none'; x.restore(); lastScene = { X, Y, w, h, who: key !== 'desk' }; return; }
    const g = x.createLinearGradient(X, Y, X, Y + h); g.addColorStop(0, `hsl(${hue} ${sat}% 24%)`); g.addColorStop(1, `hsl(${hue + 30} ${sat}% 9%)`); x.fillStyle = g; x.fillRect(X, Y, w, h); lastScene = null; };
  const INDIA = [[0.38, 0.05], [0.47, 0.1], [0.5, 0.2], [0.62, 0.3], [0.78, 0.32], [0.84, 0.4], [0.72, 0.45], [0.62, 0.52], [0.55, 0.66], [0.47, 0.88], [0.42, 0.78], [0.36, 0.6], [0.3, 0.48], [0.22, 0.42], [0.25, 0.32], [0.33, 0.25]];
  const india = (x, X, Y, s, fill, stroke) => { x.beginPath(); INDIA.forEach(([a, b], i) => (i ? x.lineTo(X + a * s, Y + b * s) : x.moveTo(X + a * s, Y + b * s))); x.closePath(); if (fill) { x.fillStyle = fill; x.fill(); } if (stroke) { x.strokeStyle = stroke; x.lineWidth = 1.5; x.stroke(); } };
  const route = (x, pts, k, col = AMB) => { x.strokeStyle = col; x.lineWidth = 2.5; x.setLineDash([5, 4]); x.beginPath(); const n = pts.length - 1, upto = k * n; pts.forEach(([a, b], i) => { if (i > upto + 1) return; const [px, py] = i <= upto ? [a, b] : [pts[i - 1][0] + (a - pts[i - 1][0]) * (upto - i + 1), pts[i - 1][1] + (b - pts[i - 1][1]) * (upto - i + 1)]; i ? x.lineTo(px, py) : x.moveTo(px, py); }); x.stroke(); x.setLineDash([]); pts.forEach(([a, b], i) => { if (i <= upto + 0.01) { x.fillStyle = W1; x.beginPath(); x.arc(a, b, 3.5, 0, 7); x.fill(); } }); };
