    takes: (x, p, w, h) => { const T = ['"Aaj hum baat… sorry"', '"Aaj hum baat karenge… umm"', '"Aaj hum baat karenge paison pe."']; T.forEach((s, i) => { const y = 40 + i * 42, k = ph(p, 0.2 + i * 0.15, 0.35 + i * 0.15); rr(x, 16, y - 15, w - 32, 30, 6, i === 2 && k > 0 ? 'rgba(110,231,183,.14)' : 'rgba(255,255,255,.05)'); tx(x, s, 26, y, 11, i < 2 && k > 0.5 ? DIM : W1, 500); if (i < 2) { x.fillStyle = RED; x.fillRect(24, y, (w - 60) * k, 2); } else if (k > 0.5) chip(x, 'Kept', w - 66, y - 9, GRN, '#062'); }); },
