    flow: (x, p, w, h) => { const N = [[50, 50, 'Idea'], [160, 50, 'Script'], [270, 50, 'Edit'], [160, 120, 'Post']]; N.forEach(([X, Y, s], i) => { const k = ph(p, i * 0.18, i * 0.18 + 0.2); x.globalAlpha = k; rr(x, X - 38, Y - 15, 76, 30, 8, 'rgba(139,92,246,.35)'); tx(x, s, X, Y, 11, W1, 700, 'center'); x.globalAlpha = 1; }); },
    whiteboard: (x, p, w, h) => { x.fillStyle = '#fafafa'; x.fillRect(0, 0, w, h); x.strokeStyle = '#111'; x.lineWidth = 2.5; x.beginPath(); const n = Math.floor(p * 60); for (let i = 0; i <= n; i++) { const a = i / 60 * Math.PI * 2; i ? x.lineTo(w / 2 + Math.cos(a) * 50, h / 2 + Math.sin(a) * 40) : x.moveTo(w / 2 + 50, h / 2); } x.stroke(); x.fillStyle = '#111'; x.beginPath(); x.arc(w / 2 + Math.cos(n / 60 * 6.28) * 50 + 10, h / 2 + Math.sin(n / 60 * 6.28) * 40 + 10, 6, 0, 7); x.fill(); },
    countdown: (x, p, w, h) => { x.fillStyle = '#0a0a0a'; x.fillRect(0, 0, w, h); const n = 5 - Math.floor(p * 5); x.strokeStyle = '#ef4444'; x.lineWidth = 6; x.beginPath(); x.arc(w / 2, h / 2, 50, -Math.PI / 2, -Math.PI / 2 + (p * 5 % 1) * 6.28); x.stroke(); tx(x, String(n), w / 2, h / 2 + 2, 44, W1, 900, 'center'); },
    l3lib: (x, p, w, h) => { scene(x, 0, 0, w, h, 330); const i = Math.floor(p * 3) % 3, k = ph(p * 3 % 1, 0, 0.3); x.globalAlpha = k; if (i === 0) { rr(x, 16, 116, 160, 36, 4, '#fff'); tx(x, 'Aarav Shah', 26, 134, 13, '#111', 800); } else if (i === 1) { x.fillStyle = AMB; x.fillRect(16, 112, 4, 40); tx(x, 'Aarav Shah', 28, 126, 14, W1, 800); tx(x, 'Founder', 28, 144, 10, AMB, 600); } else { rr(x, 16, 120, 170, 30, 15, V); tx(x, 'Aarav Shah · Founder', 30, 135, 12, W1, 700); } x.globalAlpha = 1; },
    vox: (x, p, w, h) => { x.fillStyle = '#f2e8d5'; x.fillRect(0, 0, w, h); x.fillStyle = '#e63946'; x.beginPath(); x.arc(w / 2, h / 2, 30 + 10 * Math.sin(p * 6.28), 0, 7); x.fill(); x.strokeStyle = '#1d3557'; x.lineWidth = 2; x.beginPath(); x.moveTo(30, h / 2); x.lineTo(30 + (w - 60) * ph(p, 0, 0.6), h / 2); x.stroke(); tx(x, 'WHY?', w / 2, h / 2, 16, '#fff', 900, 'center'); },
    world: (x, p, w, h) => { pic(x, MP.globe, w, h, 1.3 - 0.25 * io(p)); chip(x, 'World map · districts · 3D terrain', 12, 12, 'rgba(10,10,14,.75)'); },
    deck: (x, p, w, h) => { const i = Math.floor(p * 3) % 3, k = ph(p * 3 % 1, 0, 0.3); rr(x, 40 + (1 - k) * 40, 30, w - 80, h - 60, 8, ['#f8fafc', '#ede9fe', '#ecfeff'][i]); tx(x, ['Problem', 'Solution', 'Market'][i], w / 2 + (1 - k) * 40, h / 2, 18, '#111', 800, 'center'); },
    uidemo: (x, p, w, h) => { rr(x, 20, 16, w - 40, h - 32, 10, '#f1f5f9'); rr(x, 34, 34, 100, 20, 5, '#cbd5e1'); const k = ph(p, 0.2, 0.5); rr(x, 34, 70, (w - 68) * k, 14, 4, V); rr(x, w - 110, h - 54, 76, 26, 6, k > 0.9 ? GRN : '#94a3b8'); tx(x, k > 0.9 ? 'Done ✓' : 'Save', w - 72, h - 41, 11, W1, 800, 'center'); },
    launch: (x, p, w, h) => { x.fillStyle = '#000'; x.fillRect(0, 0, w, h); const k = ph(p, 0.1, 0.5); rr(x, w / 2 - 40 * (0.4 + 0.6 * k), 8, 80 * (0.4 + 0.6 * k), 14, 7, '#111'); x.strokeStyle = '#222'; x.strokeRect(w / 2 - 40, 8, 80, 14); x.globalAlpha = ph(p, 0.4, 0.7); tx(x, 'Hello.', w / 2, h / 2 + 10, 36, W1, 700, 'center'); x.globalAlpha = 1; },
    fxpack: (x, p, w, h) => { const i = Math.floor(p * 4) % 4; scene(x, 0, 0, w, h, 180 + i * 40, 40); if (i === 0) { x.fillStyle = 'rgba(255,255,255,.2)'; for (let j = 0; j < 8; j++) x.fillRect(0, j * 24 + (p * 200) % 24, w, 3); } if (i === 1) x.filter = 'blur(2px)'; if (i === 2) { x.globalCompositeOperation = 'difference'; x.fillStyle = '#fff'; x.fillRect(w * 0.4, 0, 20, h); x.globalCompositeOperation = 'source-over'; } x.filter = 'none'; chip(x, ['Scanlines', 'Glow', 'Glitch', 'Flash'][i], 12, 12, 'rgba(10,10,14,.75)'); },
    hookmeter: (x, p, w, h) => { const k = ph(p, 0.1, 0.7); x.strokeStyle = 'rgba(255,255,255,.12)'; x.lineWidth = 14; x.beginPath(); x.arc(w / 2, h - 30, 80, Math.PI, 0); x.stroke(); x.strokeStyle = k < 0.5 ? RED : GRN; x.beginPath(); x.arc(w / 2, h - 30, 80, Math.PI, Math.PI + Math.PI * k); x.stroke(); tx(x, k < 0.5 ? 'Slow first line' : 'Hook holds', w / 2, h - 40, 13, W1, 800, 'center'); },
    hookrewrite: (x, p, w, h) => { const H = ['"So today I want to…"', '"Nobody tells you this…"'], k = ph(p, 0.35, 0.6); tx(x, H[0], w / 2, 60, 13, k > 0.5 ? DIM : W1, 600, 'center'); if (k > 0) { x.fillStyle = RED; x.fillRect(w / 2 - 80, 60, 160 * cl(k * 2), 2); } x.globalAlpha = k; tx(x, H[1], w / 2, 110, 15, GRN, 800, 'center'); x.globalAlpha = 1; },
    retention: (x, p, w, h) => { x.strokeStyle = CY; x.lineWidth = 2.5; x.beginPath(); for (let i = 0; i <= w - 40; i += 3) { const f = i / (w - 40), y = 30 + f * 60 + (f > 0.4 && f < 0.48 ? 28 : 0) + Math.sin(f * 20) * 3; if (f > p) break; i ? x.lineTo(20 + i, y) : x.moveTo(20, y); } x.stroke(); if (p > 0.45) { mark(x, 20 + (w - 40) * 0.42, 18, RED, 'viewers leave'); } },
    shortpick: (x, p, w, h) => { lines(x, 20, 24, w - 40, 7, 18, 'rgba(255,255,255,.12)', 7); const k = ph(p, 0.3, 0.6); rr(x, 16, 24 + 2 * 18 - 4, w - 32, 18 * 3, 6, `rgba(124,58,237,${0.35 * k})`); if (k > 0.5) chip(x, 'Hook + payoff · 42 s', w - 150, 136, V); },
    seo: (x, p, w, h) => { const s = 'How I edit 10x faster in Premiere', n = Math.floor(ph(p, 0, 0.7) * s.length); rr(x, 16, 30, w - 32, 34, 8, 'rgba(255,255,255,.07)'); tx(x, s.slice(0, n), 26, 47, 12, W1, 700); tx(x, '#premierepro  #editing  #hinglish', 26, 90, 11, CY, 600); },
    ae: (x, p, w, h) => { const k = ph(p, 0.2, 0.6); rr(x, 20, 50, 90, 60, 10, '#2a1b4d'); tx(x, 'Pr', 65, 80, 22, '#c4b5fd', 900, 'center'); rr(x, w - 110, 50, 90, 60, 10, '#1a1b4d'); tx(x, 'Ae', w - 65, 80, 22, '#a5b4fc', 900, 'center'); rr(x, 120 + (w - 250) * k, 72, 16, 16, 4, AMB); },
    faceless: (x, p, w, h) => { const i = Math.floor(p * 3) % 3; scene(x, 0, 0, w, h, [30, 200, 300][i], 40); for (let j = 0; j < 20; j++) rr(x, 20 + j * 13, h - 30 - 10 * Math.abs(Math.sin(j + p * 20)), 6, 10 + 10 * Math.abs(Math.sin(j + p * 20)), 2, W1); tx(x, ['Script', 'Voice', 'Images'][i], 16, 20, 12, W1, 800); },
    chat: (x, p, w, h) => { rr(x, 20, 30, w * 0.62, 30, 10, 'rgba(255,255,255,.1)'); tx(x, '"Cut it tight, add Hinglish captions"', 30, 45, 10, W1, 600); const k = ph(p, 0.4, 0.6); x.globalAlpha = k; rr(x, w * 0.36, 80, w * 0.58, 50, 10, 'rgba(124,58,237,.35)'); tx(x, '✓ 212 cuts', w * 0.38, 96, 11, W1, 700); tx(x, '✓ Captions added', w * 0.38, 116, 11, W1, 700); x.globalAlpha = 1; },
